import { describe, it, expect } from "vitest";
import { evaluateRequirement, getMissingLeaves } from "../src/evaluate";
import {
  breadthRequirement,
  csMajorRequirement,
  globalAwarenessRequirement,
  crossBranchRequirement,
  studentFullCS,
  studentPartialCS,
  studentOneDoubleTaggedCourse,
  studentTwoDistinctCourses,
  studentWithDualPurposeCourse,
  studentSharedCourseAcrossBranches,
  studentFullBreadth,
  studentMissingOneBreadth,
} from "../src/fixtures";
import type { LeafNode } from "../src/types";

function leafKey(leaf: LeafNode): string {
  return leaf.type === "course" ? leaf.courseId : `tag:${leaf.tag}`;
}

describe("evaluateRequirement - flat AND over tag leaves (breadth)", () => {
  it("is satisfied once every breadth area has a completed course", () => {
    const result = evaluateRequirement(breadthRequirement, studentFullBreadth);
    expect(result.satisfied).toBe(true);
  });

  it("is not satisfied when one breadth area is missing", () => {
    const result = evaluateRequirement(breadthRequirement, studentMissingOneBreadth);
    expect(result.satisfied).toBe(false);
  });
});

describe("evaluateRequirement - nested AND/OR/N-of-M (3+ levels deep)", () => {
  it("is satisfied for a student who has completed everything required", () => {
    const result = evaluateRequirement(csMajorRequirement, studentFullCS);
    expect(result.satisfied).toBe(true);
  });

  it("is not satisfied for a student who is missing the lab, electives, and track", () => {
    const result = evaluateRequirement(csMajorRequirement, studentPartialCS);
    expect(result.satisfied).toBe(false);
  });

  it("lets one completed course legitimately count toward two different branches of the tree", () => {
    // COMPSCI 162 is both one of the 3 required electives AND half of the
    // Systems Track. Completing it once should help satisfy both branches --
    // this is different from the n_of_m double-counting bug below, because
    // here the two leaves live in two different parts of the tree, not in
    // the same n_of_m node.
    const result = evaluateRequirement(csMajorRequirement, studentSharedCourseAcrossBranches);
    expect(result.satisfied).toBe(true);
  });
});

describe("evaluateRequirement - N of M counting", () => {
  it("is satisfied when the student has courses backing at least n children, from distinct courses", () => {
    const result = evaluateRequirement(globalAwarenessRequirement, studentTwoDistinctCourses);
    expect(result.satisfied).toBe(true);
  });

  it("is not satisfied when fewer than n children have a backing course", () => {
    const oneTagStudent = {
      name: "only one area",
      completedCourses: [{ courseId: "COMPLIT 100", tags: ["writing_intensive"] }],
    };
    const result = evaluateRequirement(globalAwarenessRequirement, oneTagStudent);
    expect(result.satisfied).toBe(false);
  });
});

describe("evaluateRequirement - double counting", () => {
  it("allows the same course to satisfy two different leaves in two different AND branches", () => {
    const result = evaluateRequirement(crossBranchRequirement, studentWithDualPurposeCourse);
    expect(result.satisfied).toBe(true);
    expect(result.children?.[0].satisfied).toBe(true); // the specific-course leaf
    expect(result.children?.[1].satisfied).toBe(true); // the tag leaf
    expect(result.children?.[0].satisfiedBy).toEqual(["COMPSCI 61B"]);
    expect(result.children?.[1].satisfiedBy).toEqual(["COMPSCI 61B"]);
  });

  it("does NOT let one physical course satisfy two slots of the same n_of_m node", () => {
    // studentOneDoubleTaggedCourse has exactly ONE completed course, which
    // happens to carry two of the three tags checked here. A correct
    // implementation requires n=2 DISTINCT courses, so this must be false --
    // even though 2 of the 3 child leaves are individually satisfied.
    const result = evaluateRequirement(globalAwarenessRequirement, studentOneDoubleTaggedCourse);
    expect(result.satisfied).toBe(false);
  });

  it("is satisfied once a second, distinct course covers a different tag", () => {
    const result = evaluateRequirement(globalAwarenessRequirement, studentTwoDistinctCourses);
    expect(result.satisfied).toBe(true);
  });
});

describe("getMissingLeaves - explaining what's missing", () => {
  it("returns nothing for a fully satisfied requirement", () => {
    const result = evaluateRequirement(csMajorRequirement, studentFullCS);
    expect(getMissingLeaves(result)).toEqual([]);
  });

  it("returns nothing for a fully satisfied flat breadth requirement", () => {
    const result = evaluateRequirement(breadthRequirement, studentFullBreadth);
    expect(getMissingLeaves(result)).toEqual([]);
  });

  it("reports exactly the one missing tag leaf in an otherwise-complete breadth requirement", () => {
    const result = evaluateRequirement(breadthRequirement, studentMissingOneBreadth);
    const missing = getMissingLeaves(result);
    expect(missing.map((m) => leafKey(m.leaf))).toEqual(["tag:international_studies"]);
  });

  it("does not report leaves under a satisfied child (e.g. the 3 base courses Ben already has)", () => {
    const result = evaluateRequirement(csMajorRequirement, studentPartialCS);
    const missingKeys = new Set(getMissingLeaves(result).map((m) => leafKey(m.leaf)));
    expect(missingKeys.has("COMPSCI 61A")).toBe(false);
    expect(missingKeys.has("COMPSCI 61B")).toBe(false);
    expect(missingKeys.has("COMPSCI 70")).toBe(false);
    // 161 and 170 are already satisfied electives -- not missing either.
    expect(missingKeys.has("COMPSCI 161")).toBe(false);
    expect(missingKeys.has("COMPSCI 170")).toBe(false);
  });

  it("reports both lab-equivalency options, the remaining electives, and both track options for Ben", () => {
    const result = evaluateRequirement(csMajorRequirement, studentPartialCS);
    const missingKeys = new Set(getMissingLeaves(result).map((m) => leafKey(m.leaf)));

    // Machine Structures Lab (OR) -- neither taken, both are candidates.
    expect(missingKeys.has("COMPSCI 61C")).toBe(true);
    expect(missingKeys.has("COMPSCI 61CL")).toBe(true);

    // 3 of 5 electives -- 161/170 already satisfied (checked above), the
    // remaining 3 are candidates for the last slot needed.
    expect(missingKeys.has("COMPSCI 162")).toBe(true);
    expect(missingKeys.has("COMPSCI 186")).toBe(true);
    expect(missingKeys.has("COMPSCI 188")).toBe(true);

    // Track requirement (OR of ANDs) -- neither track has any course done,
    // so both tracks' courses are all reported.
    expect(missingKeys.has("COMPSCI 189")).toBe(true);
    expect(missingKeys.has("COMPSCI 182")).toBe(true);
    expect(missingKeys.has("COMPSCI 152")).toBe(true);
  });

  it("includes an ancestor-derived path on each missing leaf", () => {
    const result = evaluateRequirement(csMajorRequirement, studentPartialCS);
    const missing = getMissingLeaves(result);
    const electivesMiss = missing.find((m) => leafKey(m.leaf) === "COMPSCI 186");
    expect(electivesMiss).toBeDefined();
    expect(electivesMiss!.path).toContain("Upper-Division Electives");
  });

  it("does not report a leaf that is individually satisfied, even inside an unsatisfied n_of_m", () => {
    // Priya's one course satisfies both writing_intensive and
    // global_perspectives individually (each is its own leaf, and each is
    // satisfied on its own). The n_of_m as a whole is unsatisfied only
    // because those two satisfied leaves are backed by the same single
    // course. Per the getMissingLeaves contract, an individually-satisfied
    // child is never itself "missing" -- only quantitative_reasoning is.
    const result = evaluateRequirement(globalAwarenessRequirement, studentOneDoubleTaggedCourse);
    const missing = getMissingLeaves(result);
    expect(missing.map((m) => leafKey(m.leaf))).toEqual(["tag:quantitative_reasoning"]);
  });
});
